function compute(p) {
  var n = Math.max(2, Math.round(p.n));
  var w = [];
  for (var i = 0; i < n; i++) { var v = (p.w && p.w[i] != null) ? Number(p.w[i]) : 1; if (!isFinite(v) || v < 0) v = 0; w.push(v); }
  var S = 0; for (var j = 0; j < n; j++) S += w[j];
  var warning = null;
  if (S <= 0) { warning = 'All weights are zero; falling back to a uniform distribution.'; for (var k = 0; k < n; k++) w[k] = 1; S = n; }
  var probs = [], contrib = [], surprise = [];
  for (var m = 0; m < n; m++) {
    var pi = w[m] / S;
    probs.push(pi);
    if (pi > 0) { var s = -Math.log(pi) / Math.LN2; surprise.push(s); contrib.push(pi * s); }
    else { surprise.push(null); contrib.push(0); }
  }
  var H = 0; for (var q = 0; q < n; q++) H += contrib[q];
  var Hmax = Math.log(n) / Math.LN2;
  var labels = []; for (var r = 0; r < n; r++) labels.push('p' + (r + 1));
  var wlabels = []; for (var t = 0; t < n; t++) wlabels.push('w' + (t + 1));
  var uniform = true; for (var u = 1; u < n; u++) if (Math.abs(probs[u] - probs[0]) > 1e-9) uniform = false;
  return {
    n: n, weights: w, weight_labels: wlabels, probs: probs, labels: labels,
    contributions: contrib, surprises: surprise, H: H, Hmax: Hmax,
    H_over_Hmax: Hmax > 0 ? H / Hmax : 0, uniform: uniform, warning: warning
  };
}
